
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_x_vmt_ge_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_x_vmt_ge", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.243836518445807e+00, -4.161185192747172e+00, -4.045438040016236e+00, -3.885242477047695e+00, -3.667262692227005e+00, -3.377816417983023e+00, -3.006747955283528e+00, -2.554494071218926e+00, -2.041867193597513e+00, -1.515314709327326e+00, -1.023819806553333e+00, -6.945458072318385e-01, -5.966450461850461e-01, -4.892557085813010e-01, -3.532534650561072e-01, -2.272636208114581e-01, -1.299550010189745e-01, -4.995421484595791e-02, -6.341541879881766e-03, -6.741774113089777e-04]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


